fields.InputDefinition:
{
  "goal": "In the Version History app → Labels surface, click 'Create Label'. Confirm a wizard overlay opens showing a 3-step indicator (Entity → Records → Details) with a searchable entity list on step 1. Search for an entity (e.g. 'Users') and click it, confirming the wizard advances to the Records step. Seeing the wizard render and advance one step is success — you do NOT need to finish creating a label. Then close/cancel the wizard. Pages can take 10-30s to load — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}
